import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { copyFile, mkdtemp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { normalizeFixture } from "../tooling/fixture-oracle/src/normalize.mjs";

const root = process.cwd();
const revision = "6c87d9a026677b601e8278030dcf1ad97fe0bd86";
const piRoot = path.join(root, "original-pi");
const outputRoot = path.join(root, "contracts/fixtures/pi-6c87d9a");
const extractScript = path.join(root, "scripts/extract-pi-fixtures.mjs");
const temporary = await mkdtemp(path.join(tmpdir(), "ji-pi-fixtures-"));
const archive = path.join(temporary, "pi.tar");
const source = path.join(temporary, "source");
const generated = path.join(temporary, "generated");

const fixtures = [
  definition("pi-provider-faux-stream", "provider", "provider-faux-stream.json", "provider-faux-stream.expected.json",
    "@earendil-works/pi-ai",
    ["packages/ai/src/providers/faux.ts", "packages/ai/src/utils/event-stream.ts", "packages/ai/src/types.ts"],
    ["packages/ai/test/faux-provider.test.ts"]),
  definition("pi-agent-loop-tool-run", "agent-loop", "agent-loop-tool-run.json", "agent-loop-tool-run.expected.json",
    "@earendil-works/pi-agent-core",
    ["packages/agent/src/agent-loop.ts", "packages/agent/src/types.ts"],
    ["packages/agent/test/agent-loop.test.ts"]),
  definition("pi-session-tool-run-log", "session", "session-tool-run-log.json", "session-tool-run-log.expected.json",
    "@earendil-works/pi-agent-core",
    ["packages/agent/src/harness/session/session.ts", "packages/agent/src/harness/session/memory.ts", "packages/agent/src/harness/session/types.ts"],
    ["packages/agent/test/harness/session/memory.test.ts", "packages/agent/test/harness/session/jsonl-storage.test.ts"]),
  definition("pi-compaction-prepare", "compaction", "compaction-prepare.json", "compaction-prepare.expected.json",
    "@earendil-works/pi-agent-core",
    ["packages/agent/src/harness/compaction/compaction.ts", "packages/agent/src/harness/session/context.ts"],
    ["packages/agent/test/harness/compaction.test.ts"]),
  definition("pi-protocol-client-hello", "protocol", "protocol-client-hello.json", "protocol-client-hello.expected.json",
    "@earendil-works/pi-protocol",
    ["packages/protocol/src/codec.ts", "packages/protocol/src/framing.ts", "packages/protocol/src/cbor/encoder.ts"],
    ["packages/protocol/test/protocol.test.ts"]),
];

try {
  requireEqual(run("git", ["-C", piRoot, "rev-parse", "HEAD"]), revision, "original-pi revision");
  execFileSync("git", ["-C", piRoot, "archive", "--format=tar", "-o", archive, revision], { stdio: "inherit" });
  await mkdir(source);
  execFileSync("tar", ["-xf", archive, "-C", source], { stdio: "inherit" });
  runInherited("npm", ["ci", "--ignore-scripts"], source);
  runInherited("npm", ["run", "build", "--workspace=@earendil-works/pi-telemetry"], source);
  runInherited("npm", ["run", "hydrate-model-data", "--workspace=@earendil-works/pi-ai"], source);
  runInherited("npm", ["run", "build:offline", "--workspace=@earendil-works/pi-ai"], source);
  runInherited("npm", ["run", "build", "--workspace=@earendil-works/pi-agent-core"], source);
  runInherited("npm", ["run", "build", "--workspace=@earendil-works/pi-protocol"], source);
  const materializedScript = path.join(source, ".ji-extract-pi-fixtures.mjs");
  await copyFile(extractScript, materializedScript);
  runInherited("node", [materializedScript, generated], source);

  await rm(outputRoot, { recursive: true, force: true });
  await mkdir(outputRoot, { recursive: true });
  for (const fixture of fixtures) {
    const generatedPath = path.join(generated, path.basename(fixture.path));
    const envelope = JSON.parse(await readFile(generatedPath, "utf8"));
    requireEqual(envelope.fixtureId, fixture.id, `${fixture.domain} fixture ID`);
    requireEqual(envelope.domain, fixture.domain, `${fixture.domain} fixture domain`);
    const rawTarget = path.join(root, "contracts/fixtures", fixture.path);
    const expectedTarget = path.join(root, "contracts/fixtures", fixture.expectedPath);
    await copyFile(generatedPath, rawTarget);
    const expected = await normalizeFixture(generatedPath);
    await writeFile(expectedTarget, `${JSON.stringify(expected, null, 2)}\n`);
    fixture.rawSha256 = sha256(await readFile(generatedPath));
    fixture.expectedSha256 = sha256(await readFile(expectedTarget));
    fixture.sourceFiles = await hashes(source, fixture.sourcePaths);
    fixture.testFiles = await hashes(source, fixture.testPaths);
  }
  const oracle = {
    path: "scripts/extract-pi-fixtures.mjs",
    sha256: sha256(await readFile(extractScript)),
    publicPackages: [
      "@earendil-works/pi-ai",
      "@earendil-works/pi-agent-core",
      "@earendil-works/pi-protocol",
    ],
  };
  const manifest = {
    schemaVersion: "2.0",
    sourceRepository: "https://github.com/earendil-works/pi.git",
    sourceRevision: revision,
    sourcePackageVersion: "0.84.3",
    generation: {
      install: "npm ci --ignore-scripts",
      prepare: "npm run hydrate-model-data --workspace=@earendil-works/pi-ai",
      build: [
        "npm run build --workspace=@earendil-works/pi-telemetry",
        "npm run build:offline --workspace=@earendil-works/pi-ai",
        "npm run build --workspace=@earendil-works/pi-agent-core",
        "npm run build --workspace=@earendil-works/pi-protocol",
      ],
      oracle,
    },
    normalizationContract: "ji-pi-projection-v1",
    fixtures,
  };
  await writeFile(path.join(root, "contracts/fixtures/manifest.json"), `${JSON.stringify(manifest, null, 2)}\n`);
  process.stdout.write(`updated ${fixtures.length} Pi fixture domains from ${revision}\n`);
} finally {
  await rm(temporary, { recursive: true, force: true });
}

function definition(id, domain, filename, expectedFilename, packageName, sourcePaths, testPaths) {
  return {
    id,
    domain,
    path: `pi-6c87d9a/${filename}`,
    expectedPath: `pi-6c87d9a/${expectedFilename}`,
    package: packageName,
    sourcePaths,
    testPaths,
  };
}

async function hashes(materializedRoot, paths) {
  return Promise.all(paths.map(async (relativePath) => ({
    path: relativePath,
    sha256: sha256(await readFile(path.join(materializedRoot, relativePath))),
  })));
}

function run(executable, args, cwd = root) {
  return execFileSync(executable, args, { cwd, encoding: "utf8" }).trim();
}

function runInherited(executable, args, cwd) {
  if (process.platform === "win32") {
    execFileSync("cmd.exe", ["/d", "/s", "/c", executable, ...args], { cwd, stdio: "inherit" });
  } else {
    execFileSync(executable, args, { cwd, stdio: "inherit" });
  }
}

function requireEqual(actual, expected, name) {
  if (actual !== expected) throw new Error(`${name} mismatch: expected ${expected}, got ${actual}`);
}

function sha256(value) {
  return createHash("sha256").update(value).digest("hex");
}

